import re
with open('doc/superhero.md', 'r') as f:
    content = f.read()

# Split by registration patterns to get individual entries
pattern = r'(?:reference code|identifier|registry number|id)\s*(?:\d+)'
entries = re.split(pattern, content)

heroes = []
for i, entry in enumerate(entries):
    if i == 0 or not entry.strip():
        continue
    hero = {}
    height_match = re.search(r'height.*?(\d+\.?\d*)\s*centimeters', entry, re.IGNORECASE)
    if height_match:
        hero['height'] = float(height_match.group(1))
    if 'marvel' in entry.lower():
        hero['publisher'] = 'Marvel Comics'
    elif 'dc' in entry.lower():
        hero['publisher'] = 'DC Comics'
    if 'height' in hero or 'publisher' in hero:
        heroes.append(hero)

print(f"Total heroes with height or publisher: {len(heroes)}")
for h in heroes[:10]:
    print(h)

